#!/usr/bin/env node
// EXTERNAL CORPUS HARNESS — the standing outside ask, made drop-in
// (docs/CONTRIBUTING-CORPUS.md). The register program's most valuable missing
// data is operational documents (runbooks, rollout plans, incident procedures)
// generated by any model, prompted by someone who has NOT read this
// repository. This harness evaluates such a corpus under gates committed to
// git BEFORE any submission existed — so every future submission is
// pre-registered by construction.
//
// Usage: node external-corpus-validation.js <corpus.json>
//
// Corpus format (JSON):
//   {
//     "generator":  "<model that wrote the documents>",
//     "prompter":   "<who wrote the prompts; state whether they had read this repo>",
//     "protocol":   "<template used, selection rules, any exclusions — verbatim>",
//     "documents":  [ { "id": "<unique id>", "text": "<verbatim document>" }, ... ]
//   }
//
// PRE-REGISTERED gates (committed 2026-07-18, before any external corpus):
//
//   V1-EXT -- INSTRUMENTS ARE REGISTER-DRIVEN: OUTSIDE DESIGN SPACE < 5%
//   AND gaming-flagged < 10%. FAIL = a machine register trips an
//   instrument; the maintainer diagnoses and ledgers it, as with every
//   prior V1 failure.
//
//   S-EXT (reported, readings pre-stated): the operational-family rate,
//   read against the register-resolved baselines — human alert runbooks
//   1.6-2.0%, mandated-questionnaire plans 11.6%, unenforced/design plans
//   0.5-0.8%, inside-generated runbooks 4.2%, inside-generated plans 0.0%.
//   No band is a pass/fail here: whatever the rate is, the shuffle control
//   adjudicates whether it is structural, and the finding is published
//   either way.
//
//   G-EXT-STRUCT -- positives must be structural: 20 seeded shuffles per
//   positive (standing seed), pooled retention < 20% -> PASS-structural;
//   >= 20% -> FAIL-vocabulary (an evaluator defect on external machine
//   text, ledgered as such). Any per-text >= 10/20 FIRES decision 1's
//   reopening condition on fresh data (docs/REGISTER-DECISIONS.md).
//
//   NOT pooled into G2-EXT (authorship rule, as v3.30.0). The corpus
//   becomes development data the moment it is evaluated.
//
// Deterministic given the corpus: standing seed, seeded shuffles.
// Results: results-external-corpus-validation.json (next to the corpus).

const fs = require('fs');
const path = require('path');
const core = require(path.join(__dirname, '..', 'cathedral-core.js'));

const OPERATIONAL_FAMILY = ['OPERATIONALLY SOUND', 'OPERATIONAL INTENT'];
const SEED = 20260717;
const SHUFFLES_PER_TEXT = 20;
const MIN_PROSE = 500;

// --- helpers copied VERBATIM from core-verdict-sensitivity.js ---------------
function mulberry32(seed) {
    return function() {
        seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
        let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}
function seededShuffle(arr, rand) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}
function wordShuffle(text, rand) {
    return seededShuffle(text.split(/\s+/).filter(Boolean), rand).join(' ');
}
function stripMarkdown(md) {
    return md
        .replace(/<!--[\s\S]*?-->/g, ' ')
        .replace(/```[\s\S]*?```/g, ' ')
        .replace(/~~~[\s\S]*?~~~/g, ' ')
        .replace(/`[^`\n]*`/g, ' ')
        .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
        .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
        .replace(/^\s*\|?[-:| ]+\|[-:| ]*$/gm, ' ')
        .replace(/^#{1,6}\s*/gm, '')
        .replace(/[*_]{1,3}([^*_]+)[*_]{1,3}/g, '$1')
        .replace(/^>\s?/gm, '')
        .replace(/\|/g, ' ')
        .replace(/<[^>\n]{1,80}>/g, ' ')
        .replace(/[ \t]+/g, ' ')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

const corpusPath = process.argv[2];
if (!corpusPath || !fs.existsSync(corpusPath)) {
    console.error('usage: node external-corpus-validation.js <corpus.json>');
    console.error('corpus format: see the header of this file / docs/CONTRIBUTING-CORPUS.md');
    process.exit(2);
}
const corpus = JSON.parse(fs.readFileSync(corpusPath, 'utf8'));
for (const field of ['generator', 'prompter', 'protocol', 'documents']) {
    if (!corpus[field]) { console.error(`corpus is missing required field "${field}"`); process.exit(2); }
}
const raw = corpus.documents.map((d, i) => ({ id: d.id || `doc ${i}`, text: stripMarkdown(d.text || '') }));
const excluded = raw.filter(d => d.text.length < MIN_PROSE);
const docs = raw.filter(d => d.text.length >= MIN_PROSE);
if (docs.length === 0) { console.error('no documents survive the 500-char prose floor'); process.exit(2); }

const dist = {};
let outsideDesignSpace = 0, gamingFlagged = 0;
const gamingKinds = {};
const positives = [];
const lengths = [];
for (const d of docs) {
    lengths.push(d.text.split(/\s+/).length);
    const a = core.analyzeCathedral(d.text);
    const s = a.verdict.status;
    dist[s] = (dist[s] || 0) + 1;
    if (s === 'OUTSIDE DESIGN SPACE') outsideDesignSpace++;
    const g = a.gamingDetection.assessment;
    if (['LIKELY_GAMING', 'POSSIBLE_GAMING', 'LOW_CONTENT_UNBOUND', 'REPETITIVE_UNBOUND'].includes(g)) {
        gamingFlagged++;
        gamingKinds[g] = (gamingKinds[g] || 0) + 1;
    }
    if (OPERATIONAL_FAMILY.includes(s)) positives.push({ id: d.id, text: d.text, status: s });
}
lengths.sort((a, b) => a - b);
const famRate = positives.length / docs.length;
const odsRate = outsideDesignSpace / docs.length;
const gamingRate = gamingFlagged / docs.length;

const results = {
    generated: new Date().toISOString().slice(0, 10), seed: SEED, minProseChars: MIN_PROSE,
    corpusFile: path.basename(corpusPath),
    provenance: { generator: corpus.generator, prompter: corpus.prompter, protocol: corpus.protocol },
    evaluatorUnmodified: true,
    population: {
        documentsSubmitted: raw.length, documentsEffective: docs.length,
        excludedUnderProseFloor: excluded.map(e => e.id),
        wordLengths: { min: lengths[0], median: lengths[Math.floor(lengths.length / 2)], max: lengths[lengths.length - 1] },
        verdictDistribution: dist,
        operationalFamilyRate: (famRate * 100).toFixed(1) + '%',
        operationallySoundRate: ((dist['OPERATIONALLY SOUND'] || 0) / docs.length * 100).toFixed(1) + '%',
        outsideDesignSpaceRate: (odsRate * 100).toFixed(1) + '%',
        gamingFlaggedRate: (gamingRate * 100).toFixed(1) + '%',
        gamingKinds,
        v1ext: (odsRate < 0.05 && gamingRate < 0.10) ? 'PASS-register-driven' : 'FAIL-instrument-tripped—diagnose-and-ledger',
        sExtBaselines: 'human alert runbooks 1.6-2.0%; mandated-questionnaire plans 11.6%; unenforced/design plans 0.5-0.8%; inside-generated runbooks 4.2%; inside-generated plans 0.0%',
        positiveIds: positives.map(p => ({ id: p.id, status: p.status }))
    },
    gExtStruct: null };

console.log('═'.repeat(63));
console.log(`external corpus: ${corpus.generator} / prompts by ${corpus.prompter}`);
console.log(`  ${docs.length} effective of ${raw.length} submitted` +
    (excluded.length ? ` (${excluded.length} under the ${MIN_PROSE}-char prose floor)` : ''));
console.log(`  words: min ${lengths[0]}, median ${results.population.wordLengths.median}, max ${lengths[lengths.length - 1]}`);
console.log(`  OUTSIDE DESIGN SPACE: ${results.population.outsideDesignSpaceRate}   gaming flagged: ${results.population.gamingFlaggedRate}`,
    Object.keys(gamingKinds).length ? JSON.stringify(gamingKinds) : '');
console.log(`    → V1-EXT: ${results.population.v1ext}`);
console.log(`  operational family: ${results.population.operationalFamilyRate}   (S-EXT, reported against: ${results.population.sExtBaselines})`);
console.log(`  verdicts:`, JSON.stringify(dist));

const ctl = { pooledPositives: positives.length, trials: 0, retained: 0, perText: [] };
positives.forEach((p, pi) => {
    let r = 0;
    for (let s = 0; s < SHUFFLES_PER_TEXT; s++) {
        const rand = mulberry32(SEED + pi * 1000 + s);
        const v = core.analyzeCathedral(wordShuffle(p.text, rand)).verdict.status;
        ctl.trials++;
        if (OPERATIONAL_FAMILY.includes(v)) { ctl.retained++; r++; }
    }
    ctl.perText.push({ id: p.id, original: p.status, retainedOf20: r });
});
const rate = ctl.trials ? ctl.retained / ctl.trials : 0;
ctl.retentionRate = (rate * 100).toFixed(1) + '%';
ctl.worstText = ctl.perText.reduce((m, t) => Math.max(m, t.retainedOf20), 0);
ctl.decision1ReopeningTriggered = ctl.worstText >= 10;
ctl.gExtStruct = positives.length === 0 ? 'PASS-vacuous (no positives fired)' :
    (rate < 0.2 ? 'PASS-structural' : 'FAIL-vocabulary—evaluator-defect-on-external-machine-text');
results.gExtStruct = ctl;

console.log('═'.repeat(63));
console.log(`G-EXT-STRUCT — positives ${positives.length}, ${SHUFFLES_PER_TEXT} seeded word-shuffles each`);
if (positives.length > 0) {
    console.log(`  retention: ${ctl.retentionRate} — worst text ${ctl.worstText}/20` +
        (ctl.decision1ReopeningTriggered ? '  ⚠ DECISION 1 REOPENING CONDITION FIRED (docs/REGISTER-DECISIONS.md)' : ' (10/20 is decision 1\'s reopening trigger)'));
    ctl.perText.filter(t => t.retainedOf20 >= 4)
        .forEach(t => console.log(`    ${t.retainedOf20}/20  ${t.original}  ${t.id}`));
}
console.log(`  → G-EXT-STRUCT: ${ctl.gExtStruct}`);

const outPath = path.join(path.dirname(corpusPath), 'results-external-corpus-validation.json');
fs.writeFileSync(outPath, JSON.stringify(results, null, 2));
console.log('═'.repeat(63));
console.log('wrote ' + outPath);

process.exit(results.population.v1ext.startsWith('FAIL') || ctl.gExtStruct.startsWith('FAIL') ? 1 : 0);
